{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.tagid_final AS WITH logic_enriched AS ( SELECT TO_VARCHAR(LOT_NUMBER) AS LOGIC_LOT_NUMBER, ORIGIN, UNIQUEKEY, ORDER_DATE, EDD, SUPPLIER_ORDER_NO, TRANSFER_BRANCH_CODE, TO_PARTY, FROM_PARTY, PARTY_USER_CODE, BRANCH_SHORT_NAME AS LOGIC_BRANCH_SHORT_NAME, VOUCH_CODE, ORDER_PREFIX, ACTION_CODE, NET_ORDER_AMOUNT, ORDER_AMOUNT, TOTAL_TAX, AGENT_NAME, LOGIC_USER_CODE, PO_MRP, PENDING_QTY, TOTAL_QTY, TXN_CODE AS LOGIC_TXN_CODE, CASE WHEN TRY_TO_NUMBER(PENDING_QTY) = TRY_TO_NUMBER(TOTAL_QTY) THEN \'PENDING FOR GRN\' ELSE \'GRN DONE\' END AS PO_GRN_STATUS FROM snitch_db.maplemonk.logic_purchase_order ), tagid_filtered AS ( SELECT TO_VARCHAR(CUSTOMER_PURCHASE_ORDER) AS CUSTOMER_PURCHASE_ORDER, TO_VARCHAR(INDENT_NUMBER) AS INDENT_NUMBER, ORDER_CREATION_DATE, APPROVAL_DATE, VENDOR_NAME, VENDOR_CODE, SKU_NUMBER, PRODUCT_DESCRIPTION, GROUP_NAME6, TRY_TO_DATE(PO_DATE) AS PO_DATE, DELIVERY_ADDRESS, EAN_NUMBER, TRY_TO_NUMBER(PO_INITIAL_QTY) AS PO_INITIAL_QTY, TRY_TO_NUMBER(PO_EXTRA_PERCENTAGE) AS PO_EXTRA_PERCENTAGE, TRY_TO_NUMBER(PO_TOT_QTY) AS PO_TOT_QTY, TRY_TO_NUMBER(PO_UNIT_MRP_PRICE) AS PO_UNIT_MRP_PRICE, TRY_TO_NUMBER(RATE) AS RATE, TRY_TO_NUMBER(NET_QTY) AS NET_QTY, LOT_NUMBER, TXN_CODE, PACKNAME, PRODUCT, COLOR_NO, CHEST, SLEEVE, INSEAM, WAIST, H_CIRCUM, COLOR, FC_CODE, SKU, BRANCH_NAME, BRANCH_SHORT_NAME, TRY_TO_NUMBER(EXCHANGE_RATE) AS EXCHANGE_RATE, CURRENCY_NAME, TRANSFER_BRANCH_NAME, MFG_DATE, MANUFACTURED_MARKETED_BY, COUNTRY_OF_ORIGIN, PRODUCT_TAG_TYPE, SLOGAN, PAYMENT_STATUS, PAYMENT_DATE, EXPECTED_DELIVERY_DATE, SHIPPED_STATUS, DISPATCH_DATE, CURRENT_STATUS, LAST_UPDATED_DATE, \"Courier Partner\" AS COURIER_PARTNER, \"AWB/LR Number\" AS AWB_LR_NUMBER, PRINTING_COMPLETED_DATE FROM snitch_db.maplemonk.test_get_orders_dump WHERE NOT ( CURRENT_STATUS = \'Not Ordered Yet\' AND ( PO_DATE IS NULL OR TRY_TO_DATE(PO_DATE) < DATEADD(MONTH, -3, CURRENT_DATE) ) ) ), tagid_agg AS ( SELECT CUSTOMER_PURCHASE_ORDER, MIN(INDENT_NUMBER) AS INDENT_NUMBER, MIN(ORDER_CREATION_DATE) AS ORDER_CREATION_DATE, MIN(APPROVAL_DATE) AS APPROVAL_DATE, MIN(VENDOR_NAME) AS VENDOR_NAME, MIN(PO_DATE) AS PO_DATE, MIN(EXPECTED_DELIVERY_DATE) AS EXPECTED_DELIVERY_DATE, MIN(SHIPPED_STATUS) AS SHIPPED_STATUS, MIN(DISPATCH_DATE) AS DISPATCH_DATE, MIN(CURRENT_STATUS) AS CURRENT_STATUS, SUM(PO_INITIAL_QTY) AS PO_INITIAL_QTY, MIN(BRANCH_NAME) AS BRANCH_NAME, MIN(BRANCH_SHORT_NAME) AS BRANCH_SHORT_NAME FROM tagid_filtered GROUP BY CUSTOMER_PURCHASE_ORDER ), final_joined AS ( SELECT t.CUSTOMER_PURCHASE_ORDER, t.INDENT_NUMBER, t.ORDER_CREATION_DATE, t.APPROVAL_DATE, t.VENDOR_NAME, t.PO_DATE, t.EXPECTED_DELIVERY_DATE, t.SHIPPED_STATUS, t.DISPATCH_DATE, t.CURRENT_STATUS, t.PO_INITIAL_QTY, t.BRANCH_NAME, t.BRANCH_SHORT_NAME, l.PO_GRN_STATUS, l.ORDER_DATE AS LOGIC_ORDER_DATE, l.EDD, l.SUPPLIER_ORDER_NO, l.VOUCH_CODE, l.TRANSFER_BRANCH_CODE, l.TO_PARTY, l.FROM_PARTY, l.PARTY_USER_CODE, l.AGENT_NAME, l.PO_MRP, l.PENDING_QTY, l.TOTAL_QTY, l.NET_ORDER_AMOUNT, l.ORDER_AMOUNT, l.TOTAL_TAX, l.LOGIC_BRANCH_SHORT_NAME, l.LOGIC_LOT_NUMBER, l.LOGIC_TXN_CODE, l.ORIGIN, l.UNIQUEKEY FROM tagid_agg t LEFT JOIN logic_enriched l ON t.CUSTOMER_PURCHASE_ORDER = l.LOGIC_LOT_NUMBER ) SELECT CUSTOMER_PURCHASE_ORDER, INDENT_NUMBER, ORDER_CREATION_DATE, APPROVAL_DATE, VENDOR_NAME, PO_DATE, EXPECTED_DELIVERY_DATE, SHIPPED_STATUS, DISPATCH_DATE, CURRENT_STATUS, PO_INITIAL_QTY, BRANCH_NAME, BRANCH_SHORT_NAME, PO_GRN_STATUS, LOGIC_ORDER_DATE, EDD, SUPPLIER_ORDER_NO, VOUCH_CODE, TRANSFER_BRANCH_CODE, TO_PARTY, FROM_PARTY, PARTY_USER_CODE, AGENT_NAME, PO_MRP, PENDING_QTY, TOTAL_QTY, NET_ORDER_AMOUNT, ORDER_AMOUNT, TOTAL_TAX, LOGIC_BRANCH_SHORT_NAME, LOGIC_LOT_NUMBER, LOGIC_TXN_CODE, ORIGIN, UNIQUEKEY, NULL::VARCHAR AS METRIC, NULL::NUMBER AS DAYS, NULL::DATE AS START_DATE, NULL::DATE AS END_DATE, NULL::NUMBER(1,0) AS WITHIN_TAT FROM final_joined UNION ALL SELECT fj.CUSTOMER_PURCHASE_ORDER, fj.INDENT_NUMBER, fj.ORDER_CREATION_DATE, fj.APPROVAL_DATE, fj.VENDOR_NAME, fj.PO_DATE, fj.EXPECTED_DELIVERY_DATE, fj.SHIPPED_STATUS, fj.DISPATCH_DATE, fj.CURRENT_STATUS, fj.PO_INITIAL_QTY, fj.BRANCH_NAME, fj.BRANCH_SHORT_NAME, fj.PO_GRN_STATUS, fj.LOGIC_ORDER_DATE, fj.EDD, fj.SUPPLIER_ORDER_NO, fj.VOUCH_CODE, fj.TRANSFER_BRANCH_CODE, fj.TO_PARTY, fj.FROM_PARTY, fj.PARTY_USER_CODE, fj.AGENT_NAME, fj.PO_MRP, fj.PENDING_QTY, fj.TOTAL_QTY, fj.NET_ORDER_AMOUNT, fj.ORDER_AMOUNT, fj.TOTAL_TAX, fj.LOGIC_BRANCH_SHORT_NAME, fj.LOGIC_LOT_NUMBER, fj.LOGIC_TXN_CODE, fj.ORIGIN, fj.UNIQUEKEY, \'PO → Order\' AS METRIC, DATEDIFF( day, fj.PO_DATE, TRY_TO_DATE(fj.ORDER_CREATION_DATE) ) AS DAYS, fj.PO_DATE AS START_DATE, TRY_TO_DATE(fj.ORDER_CREATION_DATE) AS END_DATE, CASE WHEN fj.ORDER_CREATION_DATE IS NOT NULL AND DATEDIFF(day, fj.PO_DATE, TRY_TO_DATE(fj.ORDER_CREATION_DATE)) <= 1 THEN 1 ELSE 0 END AS WITHIN_TAT FROM final_joined fj WHERE fj.PO_DATE IS NOT NULL AND fj.ORDER_CREATION_DATE IS NOT NULL UNION ALL SELECT fj.CUSTOMER_PURCHASE_ORDER, fj.INDENT_NUMBER, fj.ORDER_CREATION_DATE, fj.APPROVAL_DATE, fj.VENDOR_NAME, fj.PO_DATE, fj.EXPECTED_DELIVERY_DATE, fj.SHIPPED_STATUS, fj.DISPATCH_DATE, fj.CURRENT_STATUS, fj.PO_INITIAL_QTY, fj.BRANCH_NAME, fj.BRANCH_SHORT_NAME, fj.PO_GRN_STATUS, fj.LOGIC_ORDER_DATE, fj.EDD, fj.SUPPLIER_ORDER_NO, fj.VOUCH_CODE, fj.TRANSFER_BRANCH_CODE, fj.TO_PARTY, fj.FROM_PARTY, fj.PARTY_USER_CODE, fj.AGENT_NAME, fj.PO_MRP, fj.PENDING_QTY, fj.TOTAL_QTY, fj.NET_ORDER_AMOUNT, fj.ORDER_AMOUNT, fj.TOTAL_TAX, fj.LOGIC_BRANCH_SHORT_NAME, fj.LOGIC_LOT_NUMBER, fj.LOGIC_TXN_CODE, fj.ORIGIN, fj.UNIQUEKEY, \'Production Pending\' AS METRIC, DATEDIFF( day, TRY_TO_DATE(fj.APPROVAL_DATE), CURRENT_DATE() ) AS DAYS, TRY_TO_DATE(fj.APPROVAL_DATE) AS START_DATE, CURRENT_DATE() AS END_DATE, CASE WHEN fj.APPROVAL_DATE IS NOT NULL AND (fj.DISPATCH_DATE IS NULL OR TRIM(fj.DISPATCH_DATE) = \'\') AND DATEDIFF(day, TRY_TO_DATE(fj.APPROVAL_DATE), CURRENT_DATE()) <= 7 THEN 1 ELSE 0 END AS WITHIN_TAT FROM final_joined fj WHERE fj.APPROVAL_DATE IS NOT NULL AND (fj.DISPATCH_DATE IS NULL OR TRIM(fj.DISPATCH_DATE) = \'\') UNION ALL SELECT fj.CUSTOMER_PURCHASE_ORDER, fj.INDENT_NUMBER, fj.ORDER_CREATION_DATE, fj.APPROVAL_DATE, fj.VENDOR_NAME, fj.PO_DATE, fj.EXPECTED_DELIVERY_DATE, fj.SHIPPED_STATUS, fj.DISPATCH_DATE, fj.CURRENT_STATUS, fj.PO_INITIAL_QTY, fj.BRANCH_NAME, fj.BRANCH_SHORT_NAME, fj.PO_GRN_STATUS, fj.LOGIC_ORDER_DATE, fj.EDD, fj.SUPPLIER_ORDER_NO, fj.VOUCH_CODE, fj.TRANSFER_BRANCH_CODE, fj.TO_PARTY, fj.FROM_PARTY, fj.PARTY_USER_CODE, fj.AGENT_NAME, fj.PO_MRP, fj.PENDING_QTY, fj.TOTAL_QTY, fj.NET_ORDER_AMOUNT, fj.ORDER_AMOUNT, fj.TOTAL_TAX, fj.LOGIC_BRANCH_SHORT_NAME, fj.LOGIC_LOT_NUMBER, fj.LOGIC_TXN_CODE, fj.ORIGIN, fj.UNIQUEKEY, \'Production → Dispatch\' AS METRIC, DATEDIFF( day, TRY_TO_DATE(fj.APPROVAL_DATE), TRY_TO_DATE(fj.DISPATCH_DATE) ) AS DAYS, TRY_TO_DATE(fj.APPROVAL_DATE) AS START_DATE, TRY_TO_DATE(fj.DISPATCH_DATE) AS END_DATE, CASE WHEN fj.APPROVAL_DATE IS NOT NULL AND fj.DISPATCH_DATE IS NOT NULL AND TRIM(fj.DISPATCH_DATE) <> \'\' AND DATEDIFF(day, TRY_TO_DATE(fj.APPROVAL_DATE), TRY_TO_DATE(fj.DISPATCH_DATE)) <= 7 THEN 1 ELSE 0 END AS WITHIN_TAT FROM final_joined fj WHERE fj.APPROVAL_DATE IS NOT NULL AND fj.DISPATCH_DATE IS NOT NULL AND TRIM(fj.DISPATCH_DATE) <> \'\' UNION ALL SELECT fj.CUSTOMER_PURCHASE_ORDER, fj.INDENT_NUMBER, fj.ORDER_CREATION_DATE, fj.APPROVAL_DATE, fj.VENDOR_NAME, fj.PO_DATE, fj.EXPECTED_DELIVERY_DATE, fj.SHIPPED_STATUS, fj.DISPATCH_DATE, fj.CURRENT_STATUS, fj.PO_INITIAL_QTY, fj.BRANCH_NAME, fj.BRANCH_SHORT_NAME, fj.PO_GRN_STATUS, fj.LOGIC_ORDER_DATE, fj.EDD, fj.SUPPLIER_ORDER_NO, fj.VOUCH_CODE, fj.TRANSFER_BRANCH_CODE, fj.TO_PARTY, fj.FROM_PARTY, fj.PARTY_USER_CODE, fj.AGENT_NAME, fj.PO_MRP, fj.PENDING_QTY, fj.TOTAL_QTY, fj.NET_ORDER_AMOUNT, fj.ORDER_AMOUNT, fj.TOTAL_TAX, fj.LOGIC_BRANCH_SHORT_NAME, fj.LOGIC_LOT_NUMBER, fj.LOGIC_TXN_CODE, fj.ORIGIN, fj.UNIQUEKEY, \'Production to Dispatch Lifecycle\' AS METRIC, DATEDIFF( day, TRY_TO_DATE(fj.ORDER_CREATION_DATE), COALESCE(TRY_TO_DATE(fj.DISPATCH_DATE), CURRENT_DATE()) ) AS DAYS, TRY_TO_DATE(fj.ORDER_CREATION_DATE) AS START_DATE, COALESCE(TRY_TO_DATE(fj.DISPATCH_DATE), CURRENT_DATE()) AS END_DATE, CASE WHEN fj.ORDER_CREATION_DATE IS NOT NULL AND DATEDIFF( day, TRY_TO_DATE(fj.ORDER_CREATION_DATE), COALESCE(TRY_TO_DATE(fj.DISPATCH_DATE), CURRENT_DATE()) ) <= 8 THEN 1 ELSE 0 END AS WITHIN_TAT FROM final_joined fj;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            